def link(path,label,cls='',**attrs):
 extra=' '.join(f'{k.replace("_","-")}="{E(str(v),quote=True)}"' for k,v in attrs.items())
 return f'<a class="{cls}" href="{E(path,quote=True)}" {extra}>{label}</a>'
def external(url,label,cls='text-link'):
 return link(url,label,cls,target='_blank',rel='noopener noreferrer')
def icon(name):
 paths={
 'home':'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',
 'work':'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="M8 6V3h8v3M9 11h6M12 8v6"/>',
 'network':'<rect x="8" y="2" width="8" height="6" rx="1"/><rect x="2" y="16" width="7" height="6" rx="1"/><rect x="15" y="16" width="7" height="6" rx="1"/><path d="M12 8v4M5 16v-4h14v4"/>',
 'screen':'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 22h8M12 17v5"/>',
 'server':'<rect x="3" y="2" width="18" height="8" rx="2"/><rect x="3" y="14" width="18" height="8" rx="2"/><path d="M7 6h.01M7 18h.01M12 6h5M12 18h5"/>',
 'layers':'<path d="m12 2 10 5-10 5L2 7Zm-9 10 9 5 9-5M3 17l9 5 9-5"/>',
 'shield':'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',
 'study':'<path d="m2 7 10-5 10 5-10 5ZM5 9v8c4 4 10 4 14 0V9M22 7v9"/>',
 'watch':'<path d="M3 3h7a3 3 0 0 1 2 2 3 3 0 0 1 2-2h7v17h-7a3 3 0 0 0-2 2 3 3 0 0 0-2-2H3Z M12 5v17"/>',
 'arrow':'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 'target':'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 'tool':'<path d="M14 4a6 6 0 0 0-7 8L2 18l4 4 6-6a6 6 0 0 0 8-7l-4 4-5-5Z"/>'}
 return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths.get(name,paths['screen'])+'</svg>'

def write(path,title,description,content,active=''):
 prefix='../' if '/' in path else ''
 contact=config.get('contact',{})
 navitems=[('index.html','Accueil','accueil'),('index.html#realisations','Projets','travaux'),('competences.html','Compétences','competences'),('parcours.html','Parcours','parcours'),('veille.html','Veille','veille'),('synthese.html','Synthèse E5','synthese')]
 navicons={'accueil':'home','travaux':'work','competences':'network','parcours':'study','veille':'watch','synthese':'layers'}
 nav=''.join(link(prefix+url,icon(navicons[key])+'<span>'+label+'</span>','nav-link',**({'aria_current':'page'} if key==active else {})) for url,label,key in navitems)
 canonical=f'<link rel="canonical" href="{E(BASE+"/"+path,quote=True)}"><meta property="og:url" content="{E(BASE+"/"+path,quote=True)}">' if BASE else ''
 image=(BASE+'/' if BASE else prefix)+'assets/hero-bleu.webp'
 schema={'@context':'https://schema.org','@type':'ProfilePage','name':title,'description':description,'mainEntity':{'@type':'Person','description':'Étudiant en BTS SIO SISR, candidature en alternance en support informatique.'}}
 contact_link=link(prefix+'contact.html','Échange professionnel ↗','footer-link') if contact.get('email') or contact.get('linkedin') else ''
 head=f'''<!doctype html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#03121f"><title>{E(title)}</title><meta name="description" content="{E(description,quote=True)}">{canonical}<meta property="og:type" content="website"><meta property="og:locale" content="fr_FR"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(description,quote=True)}"><meta property="og:image" content="{E(image,quote=True)}"><meta property="og:image:width" content="1536"><meta property="og:image:height" content="1024"><meta property="og:image:alt" content="Environnement technique bleu nuit : serveurs et ordinateur portable."><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><script>try{{const t=localStorage.getItem('support-blue-theme')||'auto';document.documentElement.dataset.theme=t==='auto'?'dark':t;document.documentElement.dataset.preference=t;}}catch(e){{document.documentElement.dataset.theme=matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light';}}</script><link rel="stylesheet" href="{prefix}style.css"><link rel="stylesheet" href="{prefix}bleu.css"><script src="{prefix}script.js" defer></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body><a class="skip-link" href="#contenu">Aller au contenu</a><header class="site-header"><a class="home-mark" href="{prefix}index.html" aria-label="Accueil">{icon("target")}<span class="brand-copy"><strong>Support IT</strong><small>BTS SIO SISR</small></span></a><button class="menu-button" aria-expanded="false" aria-controls="main-nav" type="button">Menu <span aria-hidden="true">☰</span></button><nav id="main-nav" aria-label="Navigation principale">{nav}</nav><div class="sidebar-status"><span></span><div>En formation<small>Systèmes et réseaux</small></div></div><button class="theme-button" type="button" aria-label="Changer le thème" title="Changer le thème"><span aria-hidden="true">◐</span></button></header><main id="contenu">'''
 foot=f'''</main><footer class="site-footer container"><span>Support informatique · BTS SIO SISR</span><div>{contact_link}{link(prefix+'confidentialite.html','Vie privée & sources')}{link('#contenu','Retour en haut ↑')}</div></footer><dialog id="image-viewer" aria-labelledby="viewer-title"><div class="viewer-bar"><h2 id="viewer-title">Agrandissement</h2><button type="button" class="viewer-close" autofocus>Fermer ×</button></div><img id="viewer-image" alt=""><p id="viewer-caption"></p></dialog></body></html>'''
 (ROOT/path).write_text(head+content+foot)
 PAGES.append(path)

def eyebrow(text):return f'<p class="eyebrow">{E(text)}</p>'
def pagehead(kicker,title,intro,action=''):
 return f'<section class="page-head container">{eyebrow(kicker)}<h1>{title}</h1><p class="lead">{intro}</p>{action}</section>'
def tags(items):return '<ul class="tags">'+''.join(f'<li>{E(i)}</li>' for i in items)+'</ul>'
def project_card(p,index=0):
 pictures={'glpi':'glpi-ticket.webp','reseau':'reseau.webp','nro':'baies.webp'}
 if p['id']=='linux':
  visual='<div class="mini-log" aria-label="Constat du diagnostic Linux"><span>Lecture du journal</span><strong>Port HTTP occupé</strong><p>Processus identifié : <b>Nginx</b></p><span>Trace anonymisée disponible</span></div>'
 else:
  alt={'glpi':'Vue anonymisée du suivi du ticket GLPI.','reseau':'Câbles Ethernet sur un équipement réseau ; vue de contexte.','nro':'Baies et équipements informatiques ; vue de contexte, sans site identifié.'}[p['id']]
  visual=f'<img src="assets/{pictures[p["id"]]}" alt="{alt}" width="800" height="500" loading="lazy" decoding="async">'
 return f'''<article class="project-card {'project-wide' if index>1 else ''}" data-category="{E(p['category'])}"><a class="project-image" href="projets/{p['id']}.html" tabindex="-1" aria-hidden="true">{visual}</a><div class="project-summary"><p class="project-meta">{E(p['category'])} <span>· {E(p['context'])}</span></p><h3>{link('projets/'+p['id']+'.html',E(p['title']))}</h3><p>{E(p['short'])}</p><div class="proof-label">{E(p['proof_type'])}</div>{link('projets/'+p['id']+'.html','Voir la démarche <span aria-hidden="true">↗</span>','text-link')}</div></article>'''

def filterbar(name,options,label):
 return f'<div class="filter-bar" role="group" aria-label="{label}">'+''.join(f'<button type="button" data-filter="{name}" data-value="{E(v)}" aria-pressed="{str(i==0).lower()}">{E(t)}</button>' for i,(v,t) in enumerate(options))+'</div>'

