home=f'''<section class="hero container"><div class="hero-copy">{eyebrow('OD')}<h1>Technicien<br><span>support informatique.</span></h1><p class="hero-line">Du terrain au support : diagnostic, rigueur,<br>traçabilité et relation utilisateur.</p><p class="hero-intro">Appui technique au NRO. Pratique de GLPI,<br>de Linux et des réseaux en formation SISR.</p><div class="actions">{link('#realisations','Voir les projets '+icon('arrow'),'button')}{link('parcours.html','Mon parcours','button button-secondary')}</div></div><div class="hero-panels" aria-label="Domaines présentés"><a class="floating-panel float-support" href="projets/glpi.html">{icon('screen')}<span><strong>Support & ITSM</strong><small>GLPI, suivi des demandes</small></span></a><a class="floating-panel float-network" href="projets/reseau.html">{icon('network')}<span><strong>Réseaux</strong><small>Ethernet, Wi-Fi, DHCP</small></span></a><a class="floating-panel float-system" href="projets/linux.html">{icon('server')}<span><strong>Systèmes Linux</strong><small>Diagnostic des services</small></span></a></div></section>
<section class="container skill-strip" aria-label="Domaines de compétences">{strip}</section>
<section class="container work-section panel" id="realisations"><div class="section-heading"><h2>Les projets et expériences</h2>{link('synthese.html','Documents techniques '+icon('arrow'),'text-link')}</div>{filterbar('projects',[('all','Tous'),('Assistance','Support'),('Administration','Systèmes'),('Réseau','Réseaux'),('Coordination','NRO')],'Filtrer les réalisations')}<p class="sr-only" id="project-count" aria-live="polite">4 réalisations affichées.</p><div class="projects-grid" tabindex="0" aria-label="Projets : défilement horizontal sur petit écran">{''.join(project_card(p,i) for i,p in enumerate(projects))}</div></section>
<section class="container dashboard-bottom"><article class="panel journey-panel"><div class="section-heading"><h2>Le parcours</h2>{link('parcours.html','Les étapes '+icon('arrow'),'text-link')}</div><div class="career-steps">{route}</div></article><article class="panel competency-panel"><div class="section-heading"><h2>Les compétences</h2>{link('competences.html','Détails '+icon('arrow'),'text-link')}</div><div class="skill-chips">{chips}</div></article></section>
<section class="container closing-panel panel"><div class="closing-icon">{icon('watch')}</div><div><h2>Une veille reliée au métier.</h2><p>Systèmes, accès et incidents : six sources officielles, datées et analysées.</p></div>{link('veille.html','Explorer la veille '+icon('arrow'),'button')}</section>'''
