def diagram(p):
 if p['id']=='reseau':
  return '''<svg class="architecture" viewBox="0 0 760 320" role="img" aria-labelledby="schema-title schema-desc"><title id="schema-title">Topologie pédagogique du TP</title><desc id="schema-desc">Un PC relié par Ethernet et un portable en Wi-Fi rejoignent un routeur, lui-même relié à un modem câble. Aucun adressage réel n’est montré.</desc><g class="schema-lines"><path d="M175 100H315V150"/><path d="M175 230H315V150" stroke-dasharray="7 6"/><path d="M435 150H555"/></g><g class="schema-box"><rect x="30" y="65" width="145" height="70" rx="7"/><rect x="30" y="195" width="145" height="70" rx="7"/><rect x="315" y="115" width="120" height="70" rx="7"/><rect x="555" y="115" width="160" height="70" rx="7"/></g><g class="schema-text"><text x="102" y="96">PC</text><text x="102" y="117" class="small">Ethernet</text><text x="102" y="226">Portable</text><text x="102" y="247" class="small">Wi-Fi / WPC300N</text><text x="375" y="146">Routeur</text><text x="375" y="167" class="small">DHCP</text><text x="635" y="146">Modem câble</text><text x="635" y="167" class="small">Simulation</text></g></svg>'''
 elif p['id']=='linux':
  labels=['Apache échoue','Port 80 occupé','Nginx identifié']
 elif p['id']=='glpi':labels=['Préparation Linux','Connexion SQL','Suivi du ticket']
 else:labels=['Priorité','Appui au diagnostic','Contrôle & suivi']
 boxes='';xs=[20,275,530]
 for x,label in zip(xs,labels):boxes+=f'<rect x="{x}" y="60" width="210" height="95" rx="7"/><text x="{x+105}" y="113">{E(label)}</text>'
 return f'<svg class="architecture process-svg" viewBox="0 0 760 220" role="img" aria-label="Schéma de méthode : {E(" puis ".join(labels))}"><g class="schema-lines"><path d="M230 107H275M485 107H530"/></g><g class="schema-box schema-text">{boxes}</g></svg>'

def evidence(p):
 if p['id']=='glpi':
  return '<div class="evidence-code"><span>Installateur GLPI · Test SQL conservé</span><pre><code>Étape 2 — Test de connexion à la base de données\nConnexion à la base de données réussie</code></pre></div>'+link('../documents/installation-glpi.txt','Préparation, erreurs et test MariaDB ↗','text-link',target='_blank',rel='noopener')+'''<figure class="evidence-figure"><button class="zoom-button" type="button" data-zoom="../assets/glpi-ticket.webp" data-caption="Vue anonymisée du ticket et de son suivi — 16 octobre 2026" aria-label="Agrandir la vue anonymisée du ticket GLPI"><img src="../assets/glpi-ticket.webp" width="1586" height="992" alt="Vue du ticket GLPI simulé avec les messages de suivi et le statut clos ; les zones d’identification sont masquées." loading="lazy"><span>Agrandir ↗</span></button><figcaption>Vue anonymisée issue de la capture du laboratoire. Les comptes et l’adresse ne sont pas diffusés.</figcaption></figure>'''
 if p['id']=='linux':return '''<div class="evidence-code"><span>Extrait du diagnostic conservé</span><pre><code>Apache : Address already in use\nCould not bind to address …:80\n\nSocket en écoute : HTTP / 80\nProcessus identifié : nginx</code></pre></div><p>Les adresses génériques et les identifiants du processus sont abrégés dans cette vue. Le fichier texte conserve les lignes utiles au constat.</p>'''+link('../documents/diagnostic-linux.txt','Lire la trace texte anonymisée ↗','text-link',target='_blank',rel='noopener')+'''<h3>Partage Samba et sauvegarde planifiée</h3><p>La même séance conserve les paramètres du partage, une liste de contenu d’archive et la planification quotidienne d’une sauvegarde.</p><div class="evidence-code"><span>Planification et contrôle du service</span><pre><code>Planification : chaque jour à 18 h\nArchive : partage Samba / commun\nCommande de contrôle : systemctl is-active cron\nRéponse : active</code></pre></div>'''+link('../documents/sauvegarde-partage.txt','Lire les extraits Samba et cron ↗','text-link',target='_blank',rel='noopener')
 return '<p class="evidence-note">'+E(p['evidence_note'])+'</p>'

for p in projects:
 st=''.join(f'<li><span>{i+1:02}</span><div><h3>{E(t)}</h3><p>{E(text)}</p></div></li>' for i,(t,text) in enumerate(p['steps']))
