  cells+=f'<td><a class="matrix-state covered" href="projets/{p["id"]}.html" aria-label="{E(p["title"]+" : "+text+". "+desc,quote=True)}">{text}</a></td>' if status!='none' else '<td><span class="matrix-state none" aria-label="Non associé"></span></td>'
